from datetime import datetime
from flask import Flask, g, jsonify, request
import sqlite3

DB = "shop.db"

app = Flask(__name__)


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    db = sqlite3.connect(DB)
    db.executescript(
        """
        CREATE TABLE IF NOT EXISTS products (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            price REAL NOT NULL,
            stock INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            product_id INTEGER NOT NULL REFERENCES products(id),
            qty INTEGER NOT NULL,
            total REAL NOT NULL,
            created_at TEXT NOT NULL
        );
        """
    )
    if db.execute("SELECT COUNT(*) FROM products").fetchone()[0] == 0:
        seed = [
            ("Mechanical Keyboard", 89.99, 25),
            ("Wireless Mouse", 34.50, 40),
            ("USB-C Hub", 49.00, 30),
            ("27\" 4K Monitor", 329.99, 12),
            ("Laptop Stand", 27.25, 50),
            ("Webcam 1080p", 59.90, 18),
            ("Desk Lamp LED", 22.75, 60),
            ("Noise-Cancel Headphones", 149.00, 8),
        ]
        db.executemany("INSERT INTO products (name, price, stock) VALUES (?,?,?)", seed)
    db.commit()
    db.close()


@app.route("/")
def index():
    with open("templates/index.html") as f:
        return f.read()


@app.route("/api/products")
def api_products():
    rows = get_db().execute("SELECT id, name, price, stock FROM products ORDER BY id").fetchall()
    return jsonify([dict(r) for r in rows])


@app.route("/api/orders", methods=["POST"])
def api_orders():
    data = request.get_json(silent=True) or {}
    try:
        product_id = int(data.get("product_id"))
        qty = int(data.get("qty"))
    except (TypeError, ValueError):
        return jsonify({"error": "product_id and qty must be integers"}), 400
    if qty < 1:
        return jsonify({"error": "qty must be >= 1"}), 400

    db = get_db()
    product = db.execute("SELECT id, name, price, stock FROM products WHERE id=?", (product_id,)).fetchone()
    if product is None:
        return jsonify({"error": "product not found"}), 404
    if product["stock"] < qty:
        return jsonify({"error": "insufficient stock", "available": product["stock"]}), 409

    total = round(product["price"] * qty, 2)
    created_at = datetime.now().isoformat(timespec="seconds")
    with db:
        db.execute("UPDATE products SET stock = stock - ? WHERE id = ?", (qty, product_id))
        cur = db.execute(
            "INSERT INTO orders (product_id, qty, total, created_at) VALUES (?,?,?,?)",
            (product_id, qty, total, created_at),
        )
    order = db.execute("SELECT id, product_id, qty, total, created_at FROM orders WHERE id=?", (cur.lastrowid,)).fetchone()
    return jsonify({**dict(order), "product_name": product["name"]}), 201


if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=5000)

